def solve_n_queens(n=8):
    def is_safe(board, row, col):
        # Check column
        for i in range(row):
            if board[i] == col:
                return False
        # Check upper-left diagonal
        for i, j in zip(range(row-1, -1, -1), range(col-1, -1, -1)):
            if board[i] == j:
                return False
        # Check upper-right diagonal
        for i, j in zip(range(row-1, -1, -1), range(col+1, n)):
            if board[i] == j:
                return False
        return True

    def solve(board, row):
        if row == n:
            return board[:]
        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                result = solve(board, row + 1)
                if result is not None:
                    return result
                board[row] = -1
        return None

    board = [-1] * n
    return solve(board, 0)

solution = solve_n_queens(8)
print(solution)

def verify_solution(solution):
    n = len(solution)
    for i in range(n):
        for j in range(i+1, n):
            # Same column
            if solution[i] == solution[j]:
                return False, f"Queens at rows {i} and {j} share column {solution[i]}"
            # Same diagonal
            if abs(solution[i] - solution[j]) == abs(i - j):
                return False, f"Queens at rows {i} and {j} are on same diagonal"
    return True, "Valid solution"

solution = [0, 4, 7, 5, 2, 6, 1, 3]
valid, msg = verify_solution(solution)
print(f"Valid: {valid}, {msg}")
